/* Classic syntax */
@media (min-width: 768px) {
  .sidebar { display: block; }  /* only on screens >= 768px */
}

/* Modern range syntax (Level 4) */
@media (width >= 768px) {
  .sidebar { display: block; }
}

/* Range: between two widths */
@media (600px <= width < 1024px) {
  .layout { grid-template-columns: 1fr 1fr; }
}

/* Combining conditions */
@media (min-width: 768px) and (orientation: landscape) {
  .hero { min-height: 60vh; }
}

/* BASE STYLES — mobile (no query) */
.cards {
  display: grid;
  grid-template-columns: 1fr;  /* single column on mobile */
  gap: 16px;
}

nav ul {
  display: none;               /* hide nav links on mobile */
}

/* TABLET — 640px+ */
@media (min-width: 640px) {
  .cards {
    grid-template-columns: 1fr 1fr;  /* two columns */
  }
}

/* DESKTOP — 1024px+ */
@media (min-width: 1024px) {
  .cards {
    grid-template-columns: repeat(3, 1fr);  /* three columns */
  }
  nav ul {
    display: flex;
    gap: 24px;
  }
}

/* Respect OS dark mode preference */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0e1116;
    --text: #e2e8f0;
  }
}

/* Reduce motion for users who need it */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* Coarse pointer (touch device) — make touch targets larger */
@media (pointer: coarse) {
  button { min-height: 44px; min-width: 44px; }
}
